css:
.nav {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px 20px;
  background: #18181b;
  color: #fafafa;
}

.logo {
  font-weight: 700;
}

.links {
  display: flex;
  gap: 16px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.links a {
  color: inherit;
  text-decoration: none;
}

.cta {
  margin-left: auto; /* eats the free space */
  padding: 6px 12px;
  border: 0;
  border-radius: 4px;
  background: #f97316;
  color: #fff;
}
